style.css:
@-moz-document domain("google.com") {
/* --- 1. MANTENER EL ESTILO BASE (Rosa pastel en letras y fondo oscuro) --- */
    body, 
    span, 
    a, 
    div:not(.lnXGbe), /* Evitar interferir con el logo principal en la búsqueda */
    .NKvO3, 
    .gb_V,
    .footer-content a,
    input[type="text"] {
        color: #FFB7C5 !important; /* Rosa pastel */
    }

    /* --- 2. EL LOGO EN ROSA Y CON RESPLANDOR --- */
    /* Apuntamos al contenedor del logo de Google */
    .k1zIA, #hplogo {
        /* Filtro de color: invierte los colores, ajusta tono a rosa pastel y sube brillo */
        filter: invert(70%) sepia(30%) saturate(300%) hue-rotate(300deg) brightness(1.2) contrast(1.1) !important;
        /* Resplandor externo suave del logo */
        filter: drop-shadow(0 0 10px #FFB7C5) !important; 
    }

    /* --- 3. LA BARRA DE BÚSQUEDA CON "GLOW" (GLOW-UP) --- */
    .RNNXgb, .SDkpf {
        background-color: rgba(255, 182, 193, 0.25) !important; /* Rosa un poco más visible */
        border: 2px solid #FFB7C5 !important; /* Borde más definido */
        border-radius: 24px;
        
        /* El "Glow": Múltiples sombras para un efecto suave y potente */
        box-shadow: 
            0 0 15px rgba(255, 182, 193, 0.7),    /* Brillo interno de la línea */
            0 0 30px rgba(255, 182, 193, 0.4),    /* Brillo medio */
            0 0 45px rgba(255, 182, 193, 0.2);    /* Brillo externo muy sutil */
        transition: box-shadow 0.3s ease; /* Para un efecto suave al pasar el mouse */
    }
    
    /* Pequeño glow extra cuando pasas el mouse por encima o haces clic */
    .RNNXgb:hover, .RNNXgb:focus-within {
        box-shadow: 
            0 0 20px rgba(255, 182, 193, 0.8),
            0 0 40px rgba(255, 182, 193, 0.5),
            0 0 60px rgba(255, 182, 193, 0.3);
    }

    /* --- 4. BOTONES CENTRALES Y EL PIE DE PÁGINA --- */
    .FPdoLc input[type="submit"], .gNO89b {
        background-color: rgba(255, 182, 193, 0.2) !important;
        color: #FFB7C5 !important;
        border-radius: 4px;
        border: 1px solid #FFB7C5 !important;
        /* Glow sutil en los botones */
        box-shadow: 0 0 5px rgba(255, 182, 193, 0.5) !important;
    }
    
    .K72Sdd, .fbar, footer {
        background-color: rgba(255, 182, 193, 0.1) !important;
        border-top: 1px solid #FFB7C5 !important;
    }

    /* Pestaña superior (header) */
    .gb_Td, .gb_Sd {
        background-color: rgba(255, 182, 193, 0.15) !important;
    }
}
